use std::{time::Instant};
use axum::{body::{Body,Bytes},extract::{DefaultBodyLimit,State},http::{header,HeaderMap,HeaderValue,StatusCode},response::{IntoResponse,Response},routing::{get,post},Json,Router};
use futures_util::{StreamExt,stream};
use serde::{Deserialize,Serialize};
use serde_json::Value;
use sha2::{Digest,Sha256};
use crate::{AegisError,AppState,FaultKind,OperationalEvent};

#[derive(Clone,Debug,Serialize,Deserialize)]
pub struct ChatMessage{pub role:String,pub content:Value}
#[derive(Clone,Debug,Serialize,Deserialize)]
pub struct ChatCompletionRequest{pub model:String,pub messages:Vec<ChatMessage>,#[serde(default)]pub stream:bool,#[serde(default)]pub temperature:Option<f32>,#[serde(flatten)]pub extra:serde_json::Map<String,Value>}

pub fn router(state:AppState)->Router{let limit=state.config.max_request_bytes;Router::new().route("/healthz",get(||async{StatusCode::NO_CONTENT})).route("/readyz",get(||async{StatusCode::NO_CONTENT})).route("/v1/chat/completions",post(chat)).layer(DefaultBodyLimit::max(limit)).with_state(state)}

async fn chat(State(state):State<AppState>,headers:HeaderMap,Json(req):Json<ChatCompletionRequest>)->Result<Response,ProxyError>{
 let started=Instant::now();if req.model.trim().is_empty()||req.messages.is_empty(){return Err(ProxyError::BadRequest("model and messages are required"));}if req.temperature.is_some_and(|v|!v.is_finite()||!(0.0..=2.0).contains(&v)){return Err(ProxyError::BadRequest("temperature must be finite and in [0,2]"));}
 let fault=state.faults.detect(&headers);match fault{Some(FaultKind::RateLimit)=>{state.metrics.event(OperationalEvent::Fault("429"));state.metrics.record(started.elapsed(),None);return Ok(crate::fault::response(FaultKind::RateLimit));},Some(FaultKind::ContextLength)=>{state.metrics.event(OperationalEvent::Fault("400-context"));state.metrics.record(started.elapsed(),None);return Ok(crate::fault::response(FaultKind::ContextLength));},Some(FaultKind::DisconnectAfterTenChunks) if !req.stream=>return Ok(crate::fault::response(FaultKind::DisconnectAfterTenChunks)),_=>{}}
 let prompt=serde_json::to_string(&req.messages)?;let vector=state.embedder.embed(&prompt).await?;let eligible=state.config.semantic_cache_enabled&&!req.stream&&req.temperature.unwrap_or(0.0)==0.0;let fingerprint=fingerprint(&req)?;
 if eligible{if let Some(hit)=state.vectors.query(&vector,&req.model,&fingerprint){state.metrics.record(started.elapsed(),Some(true));state.metrics.event(OperationalEvent::CacheHit);let mut response=Response::new(Body::from(hit.response));response.headers_mut().insert("x-proxy-cache",HeaderValue::from_static("HIT-Semantic"));response.headers_mut().insert(header::CONTENT_TYPE,HeaderValue::from_static("application/json"));return Ok(response);}}
 let endpoint=format!("{}/v1/chat/completions",state.config.upstream_base_url.trim_end_matches('/'));let mut upstream=state.upstream.post(endpoint).json(&req);if let Some(token)=state.config.upstream_bearer_token.as_deref(){upstream=upstream.bearer_auth(token);}let upstream=upstream.send().await.map_err(|e|{state.metrics.event(OperationalEvent::UpstreamFailure);ProxyError::Upstream(e)})?;let status=upstream.status();let headers=upstream.headers().clone();
 if req.stream{let source=upstream.bytes_stream();let stream=if matches!(fault,Some(FaultKind::DisconnectAfterTenChunks)){state.metrics.event(OperationalEvent::Fault("disconnect-10"));let mut count=0usize;Box::pin(stream::unfold((source,count),| (mut source,mut count)|async move{if count>=10{return Some((Err(std::io::Error::other("AegisLLM injected truncated stream")),(source,count+1)));}match source.next().await{Some(Ok(chunk))=>{count+=1;Some((Ok::<Bytes,std::io::Error>(chunk),(source,count)))},Some(Err(e))=>Some((Err(std::io::Error::other(e)),(source,10))),None=>None}}).take(11)) as futures_util::stream::BoxStream<'static,Result<Bytes,std::io::Error>>}else{Box::pin(source.map(|r|r.map_err(std::io::Error::other))) as futures_util::stream::BoxStream<'static,Result<Bytes,std::io::Error>>};let mut response=Response::new(Body::from_stream(stream));*response.status_mut()=status;copy_headers(&headers,response.headers_mut());state.metrics.record(started.elapsed(),Some(false));return Ok(response);}
 let body=upstream.bytes().await?;if eligible&&status.is_success()&&serde_json::from_slice::<Value>(&body).is_ok(){state.vectors.insert(cache_key(&req,&prompt),vector,body.clone(),req.model.clone(),fingerprint);state.metrics.event(OperationalEvent::CacheInsert);}let mut response=Response::new(Body::from(body));*response.status_mut()=status;copy_headers(&headers,response.headers_mut());response.headers_mut().insert("x-proxy-cache",HeaderValue::from_static("MISS-Semantic"));state.metrics.record(started.elapsed(),Some(false));Ok(response)
}
fn copy_headers(from:&HeaderMap,to:&mut HeaderMap){for name in [header::CONTENT_TYPE,header::CACHE_CONTROL]{if let Some(value)=from.get(&name){to.insert(name,value.clone());}}}
fn fingerprint(req:&ChatCompletionRequest)->Result<[u8;32],AegisError>{let mut compatible=req.clone();compatible.messages.clear();compatible.stream=false;let digest=Sha256::digest(serde_json::to_vec(&compatible)?);let mut out=[0;32];out.copy_from_slice(&digest);Ok(out)}
fn cache_key(req:&ChatCompletionRequest,prompt:&str)->String{let mut h=Sha256::new();h.update(req.model.as_bytes());h.update(prompt.as_bytes());h.update(req.temperature.unwrap_or(0.0).to_bits().to_le_bytes());format!("{:x}",h.finalize())}
#[derive(Debug,thiserror::Error)]enum ProxyError{#[error("bad request: {0}")]BadRequest(&'static str),#[error(transparent)]Aegis(#[from]AegisError),#[error(transparent)]Upstream(#[from]reqwest::Error),#[error(transparent)]Json(#[from]serde_json::Error)}
impl IntoResponse for ProxyError{fn into_response(self)->Response{let(status,message)=match &self{Self::BadRequest(m)=>(StatusCode::BAD_REQUEST,(*m).to_owned()),Self::Aegis(AegisError::InvalidRequest(m))=>(StatusCode::BAD_REQUEST,m.clone()),Self::Upstream(_)=>(StatusCode::BAD_GATEWAY,"upstream request failed".into()),_=>(StatusCode::INTERNAL_SERVER_ERROR,"proxy internal error".into())};(status,Json(serde_json::json!({"error":{"message":message}}))).into_response()}}
